from pathlib import Path

p = Path('main/device_config.c')
s = p.read_text()
needle = '''    return root;\n}\n\n/** @brief Atomically replace the sole authoritative internal configuration. */\n'''
insert = '''    return root;\n}\n\n/** @brief Check whether the stored document already matches RFScout's canonical serialization. */\nstatic esp_err_t config_file_is_canonical( bool *a_canonical )\n{\n    if( NULL == a_canonical )\n    {\n        return ESP_ERR_INVALID_ARG;\n    }\n    *a_canonical = false;\n\n    cJSON *root = build_json( false, 0, NULL );\n    if( NULL == root )\n    {\n        return ESP_ERR_NO_MEM;\n    }\n    char *text = cJSON_Print( root );\n    cJSON_Delete( root );\n    if( NULL == text )\n    {\n        return ESP_ERR_NO_MEM;\n    }\n\n    FILE *file = fopen( RFSCOUT_INTERNAL_CONFIG_PATH, "rb" );\n    if( NULL == file )\n    {\n        free( text );\n        return ( ENOENT == errno ) ? ESP_ERR_NOT_FOUND : ESP_FAIL;\n    }\n\n    const size_t text_length = strlen( text );\n    bool matches = true;\n    for( size_t offset = 0U; offset < text_length; )\n    {\n        char buffer[ 256 ];\n        const size_t remaining = text_length - offset;\n        const size_t wanted = remaining < sizeof( buffer ) ? remaining : sizeof( buffer );\n        const size_t count = fread( buffer, 1U, wanted, file );\n        if( count != wanted || 0 != memcmp( buffer, text + offset, wanted ) )\n        {\n            matches = false;\n            break;\n        }\n        offset += wanted;\n    }\n    if( matches )\n    {\n        matches = ( '\\n' == fgetc( file ) ) && ( EOF == fgetc( file ) ) && !ferror( file );\n    }\n\n    fclose( file );\n    free( text );\n    *a_canonical = matches;\n    return ESP_OK;\n}\n\n/** @brief Atomically replace the sole authoritative internal configuration. */\n'''
if needle not in s:
    raise SystemExit('build_json insertion point not found')
s = s.replace(needle, insert, 1)
old = '''    if( ESP_OK == result )\n    {\n        if( config_store_import_pending() )\n        {\n            const esp_err_t upgrade_result = device_config_save( false, 0, NULL );\n            if( ESP_OK != upgrade_result )\n            {\n                config_dirty = true;\n                ESP_LOGW( TAG,\n                          "configuration normalization save failed: %s",\n                          esp_err_to_name( upgrade_result ) );\n            }\n            else\n            {\n                if( config_store_import_pending() )\n                {\n                    const esp_err_t finalize_result = config_store_finalize_import();\n                    if( ESP_OK == finalize_result )\n                    {\n                        rfscout_event_emit( RFSCOUT_EVENT_CONFIG_IMPORTED,\n                                            RFSCOUT_EVENT_SOURCE_SYSTEM,\n                                            (int32_t)RFSCOUT_CONFIG_SCHEMA_VERSION );\n                    }\n                    else\n                    {\n                        ESP_LOGW( TAG,\n                                  "configuration import finalization failed: %s",\n                                  esp_err_to_name( finalize_result ) );\n                    }\n                }\n            }\n        }\n        else\n        {\n            config_dirty = false;\n        }\n\n'''
new = '''    if( ESP_OK == result )\n    {\n        bool canonical = false;\n        const esp_err_t canonical_result = config_file_is_canonical( &canonical );\n        if( ESP_OK != canonical_result )\n        {\n            ESP_LOGW( TAG,\n                      "configuration canonical comparison failed: %s",\n                      esp_err_to_name( canonical_result ) );\n        }\n\n        if( config_store_import_pending() || !canonical )\n        {\n            const esp_err_t save_result = device_config_save( false, 0, NULL );\n            if( ESP_OK != save_result )\n            {\n                config_dirty = true;\n                ESP_LOGW( TAG,\n                          "configuration canonical save failed: %s",\n                          esp_err_to_name( save_result ) );\n            }\n            else if( config_store_import_pending() )\n            {\n                const esp_err_t finalize_result = config_store_finalize_import();\n                if( ESP_OK == finalize_result )\n                {\n                    rfscout_event_emit( RFSCOUT_EVENT_CONFIG_IMPORTED,\n                                        RFSCOUT_EVENT_SOURCE_SYSTEM,\n                                        (int32_t)RFSCOUT_CONFIG_SCHEMA_VERSION );\n                }\n                else\n                {\n                    ESP_LOGW( TAG,\n                              "configuration import finalization failed: %s",\n                              esp_err_to_name( finalize_result ) );\n                }\n            }\n        }\n        else\n        {\n            config_dirty = false;\n        }\n\n'''
if old not in s:
    raise SystemExit('init block not found')
s = s.replace(old, new, 1)
p.write_text(s)

p = Path('docs/CONFIGURATION.md')
s = p.read_text()
s = s.replace('Visual themes are **Indoor**, **Outdoor**, and **Night** and affect colors only. Unsupported theme values, including legacy aliases such as `discipline`, retain the compiled default and are reported as configuration errors.', 'Visual themes are **Indoor**, **Outdoor**, and **Night** and affect colors only. Unsupported theme values retain the compiled default and are reported as configuration errors.')
s = s.replace('Internal schema compatibility is deliberately simple while RFScout remains pre-1.0: the stored internal document must match the firmware\'s current schema. An incompatible internal document is replaced by current defaults rather than migrated through backup/recovery files.', 'Internal schema compatibility is deliberately simple while RFScout remains pre-1.0: the stored internal document must match the firmware\'s current schema. An incompatible internal document is replaced by current defaults rather than migrated through backup/recovery files. A current-schema document is rewritten once when its effective parsed values differ from RFScout\'s canonical serialization, so defaulted invalid values, unknown fields, aliases, and noncanonical formatting do not persist as authoritative state.')
p.write_text(s)

p = Path('docs/ROADMAP.md')
s = p.read_text()
s = s.replace('- unsupported or invalid current-schema field values retain their compiled defaults; legacy theme aliases are not supported;\n', '- unsupported or invalid current-schema field values retain their compiled defaults and are rewritten canonically;\n')
p.write_text(s)
